      SUBROUTINE TITLEC---- PERFORM "TITLE" COMMANDC------------------------------------------------------------------      INCLUDE 'IMAGE.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'C--------------------------------------------------------------------      CHARACTER*15    KNAME      INTEGER         I, IBEG, IEND, ILAST, IST, LNAMEC--------------------------------------------------------------------C    5 CALL RDLINE      IF (.NOT. ENDFIL) THEN        IBEG = 1   10   CALL RDNEXT        IF (ENDFIL) GO TO 200        IF (ITEM .EQ. QUOTE .OR. ITEM .EQ. APOST) THEN          IBEG = ICOL + 1          GO TO 20        ELSE IF (INDEX(ALPHA,ITEM) .NE. 0) THEN          CALL RDWORD(KNAME,LNAME)          IF (KNAME(1:4) .EQ. 'SENT') THEN            ENDFIL = .TRUE.            GO TO 200          ELSE            GO TO 10          ENDIF        ELSE IF (ITEM .EQ. ';') THEN          GO TO 5        ENDIFC   20   IST = IBEG        DO 30 I = IST, 80        ILAST = I        IF (KLINE(I) .EQ. BLANK) GO TO 30        IF (KLINE(I) .EQ. QUOTE .OR. KLINE(I) .EQ. APOST) GO TO 80        IBEG = I        GO TO 40   30   CONTINUEC   40   IF (IBEG .LT. 80) GO TO 50        IBEG = 1        IEND = 80        GO TO 100C   50   IEND = 80        IST = IBEG        DO 60 I = IST, 80        IF (KLINE(I) .NE. QUOTE .AND. KLINE(I) .NE. APOST) GO TO 60        IEND = I - 1        GO TO 100   60   CONTINUE        GO TO 100   80   IEND = ILAST - 1  100   IMAGE = KTEXT(IBEG:IEND)        ICOL = 81        ITEM = KLINE(ICOL)      ENDIF  200 CONTINUE      RETURN      END